const b = $input.first().json.body || $input.first().json;
const date = String(b.date || '');
const location = String(b.location || 'Ischgl');
const diff = Number(b.difference);
const ok = /^\d{4}-\d{2}-\d{2}$/.test(date) && isFinite(diff);
const d = new Date(date + 'T00:00:00Z');
const addDays = (n) => { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x.toISOString().slice(0, 10); };
return [{ json: { ok, date, location, difference: diff, direction: diff < 0 ? 'negative' : 'positive', from: addDays(-7), to: addDays(7) } }];

const p = $('Prepare').first().json;
if (!p.ok) return [{ json: { error: 'invalid_input', expected: { date: 'YYYY-MM-DD', location: 'text', difference: 'number (actual minus forecast)' } } }];
const items = (name) => $(name).all().map(i => i.json).filter(x => x && x.startDate && x.endDate);
const school = items('School holidays');
const publicH = items('Public holidays');
const wxRaw = $('Weather').first().json;
const daily = wxRaw && wxRaw.daily ? wxRaw.daily : null;
const tmax = daily && daily.temperature_2m_max ? daily.temperature_2m_max[0] : null;
const precip = daily && daily.precipitation_sum ? daily.precipitation_sum[0] : null;
const snow = daily && daily.snowfall_sum ? daily.snowfall_sum[0] : null;
const d = new Date(p.date + 'T00:00:00Z');
const gaps = [];
if (!school.length && !$('School holidays').all().length) gaps.push('School holiday data not available');
if (!daily) gaps.push('Weather not available for this date (outside the forecast range or API error)');
const cands = [];
const add = (reason, influence, weight, evidence) => cands.push({ reason, influence, weight, evidence });
const inRange = (h) => h.startDate <= p.date && p.date <= h.endDate;
const daysTo = (iso) => (new Date(iso + 'T00:00:00Z') - d) / 86400000;
if (school.some(inRange)) add('School holidays on this date', 'positive', 0.8, 'Date is inside a school holiday period (Tyrol)');
else {
  const starts = school.find(h => daysTo(h.startDate) > 0 && daysTo(h.startDate) <= 3);
  if (starts) add('School holidays start within 3 days', 'positive', 0.5, 'Holidays begin ' + starts.startDate);
  const ended = school.find(h => daysTo(h.endDate) < 0 && daysTo(h.endDate) >= -3);
  if (ended) add('School holidays ended within 3 days', 'negative', 0.6, 'Holidays ended ' + ended.endDate);
}
const ph = publicH.find(inRange);
if (ph) add('Public holiday on this date', 'positive', 0.7, ph.name && ph.name[0] ? ph.name[0].text : 'public holiday');
else if (publicH.some(h => Math.abs(daysTo(h.startDate)) <= 1)) add('Long weekend or bridge day', 'positive', 0.4, 'Public holiday within 1 day');
const wd = d.getUTCDay();
if (wd === 5 || wd === 6 || wd === 0) add('Friday, Saturday or Sunday night', 'negative', 0.35, 'In the 2025/26 data, Fri, Sat and Sun stays fell most short of forecast');
const winter = [10, 11, 0, 1, 2, 3].includes(d.getUTCMonth());
if (precip !== null && precip >= 10) add('Heavy precipitation', 'negative', 0.6, precip + ' mm');
if (snow !== null && snow >= 5) add('Fresh snow', 'positive', 0.7, snow + ' cm new snow');
if (tmax !== null && winter && tmax >= 8 && (snow === null || snow < 5)) add('Warm day with little snow', 'negative', 0.5, 'max ' + tmax + ' °C, snow ' + (snow ?? 0) + ' cm');
const ranked = [...cands].sort((a, b) => b.weight - a.weight);
const supports = ranked.filter(c => (p.direction === 'negative' ? c.influence === 'negative' : c.influence === 'positive'));
const other = ranked.filter(c => !supports.includes(c));
const top = [...supports, ...other].slice(0, 3).map((c, i) => ({ rank: i + 1, reason: c.reason, influence: c.influence, weight: c.weight, supports_observed_direction: supports.includes(c), evidence: c.evidence }));
return [{ json: { date: p.date, location: p.location, difference: p.difference, direction: p.direction, top_reasons: top, candidates_checked: cands.length, data_gaps: gaps, method: 'Rule-based: school and public holidays, weekday pattern, weather (Open-Meteo). Not yet included: regional trend, events, booking pace.' } }];
